import SwiftUI

struct CardGridItemView: View {
    let card: PictureCard
    let onTap: () -> Void
    let onLongPress: () -> Void
    var isEditMode: Bool = false

    var body: some View {
        Button {
            onTap()
        } label: {
            VStack(spacing: 6) {
                cardImage
                    .frame(width: 56, height: 56)
                    .clipShape(RoundedRectangle(cornerRadius: 8))

                Text(card.displayName)
                    .font(.callout)
                    .fontWeight(.semibold)
                    .lineLimit(2)
                    .minimumScaleFactor(0.6)
                    .multilineTextAlignment(.center)
                    .foregroundStyle(.primary)
            }
            .frame(maxWidth: .infinity)
            .padding(.vertical, 10)
            .padding(.horizontal, 4)
            .background(
                RoundedRectangle(cornerRadius: 12)
                    .fill(categoryColor(for: card.category).opacity(0.08))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 12)
                    .stroke(
                        isEditMode
                            ? categoryColor(for: card.category)
                            : categoryColor(for: card.category).opacity(0.3),
                        lineWidth: isEditMode ? 2 : 1
                    )
            )
        }
        .buttonStyle(.plain)
        .simultaneousGesture(
            LongPressGesture(minimumDuration: 0.5)
                .onEnded { _ in
                    onLongPress()
                }
        )
        .accessibilityLabel(card.displayName)
        .accessibilityHint(isEditMode ? "タップで編集、ドラッグして並べ替え" : "タップして文に追加")
    }

    @ViewBuilder
    private var cardImage: some View {
        if card.isPreset, let imageName = card.presetImageName, UIImage(named: imageName) != nil {
            Image(imageName)
                .resizable()
                .scaledToFill()
        } else if card.isPreset, let symbolName = card.presetImageName {
            Image(systemName: symbolName)
                .font(.title)
                .foregroundStyle(categoryColor(for: card.category))
        } else if let uiImage = ImageStorageService.load(id: card.id) {
            Image(uiImage: uiImage)
                .resizable()
                .scaledToFill()
        } else {
            Image(systemName: "photo")
                .font(.title)
                .foregroundStyle(.gray)
        }
    }
}

import SwiftUI

struct SentenceCardView: View {
    let card: PictureCard
    let onRemove: () -> Void

    var body: some View {
        Button(action: onRemove) {
            VStack(spacing: 2) {
                cardImage
                    .frame(width: 44, height: 44)
                    .clipShape(RoundedRectangle(cornerRadius: 6))

                Text(card.displayName)
                    .font(.caption2)
                    .fontWeight(.medium)
                    .lineLimit(1)
                    .minimumScaleFactor(0.7)
            }
            .padding(4)
            .frame(width: 60, height: 70)
            .background(
                RoundedRectangle(cornerRadius: 8)
                    .fill(categoryColor(for: card.category).opacity(0.15))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(categoryColor(for: card.category), lineWidth: 1.5)
            )
        }
        .buttonStyle(.plain)
        .accessibilityLabel("\(card.displayName)を削除")
    }

    @ViewBuilder
    private var cardImage: some View {
        if card.isPreset, let imageName = card.presetImageName, UIImage(named: imageName) != nil {
            Image(imageName)
                .resizable()
                .scaledToFill()
        } else if card.isPreset, let symbolName = card.presetImageName {
            Image(systemName: symbolName)
                .font(.title2)
                .foregroundStyle(categoryColor(for: card.category))
        } else if let uiImage = ImageStorageService.load(id: card.id) {
            Image(uiImage: uiImage)
                .resizable()
                .scaledToFill()
        } else {
            Image(systemName: "photo")
                .font(.title2)
                .foregroundStyle(.gray)
        }
    }
}

func categoryColor(for category: String) -> Color {
    switch category {
    case "場所": return .blue
    case "動作": return .orange
    case "気持ち": return .pink
    case "食べ物": return .green
    case "人": return .purple
    case "生活": return .teal
    case "いつ": return .indigo
    default: return .gray
    }
}

