                .resizable()
                .scaledToFill()
        } else {
            Image(systemName: "photo")
                .font(.title2)
                .foregroundStyle(.gray)
        }
    }
}

func categoryColor(for category: String) -> Color {
    switch category {
    case "場所": return .blue
    case "動作": return .orange
    case "気持ち": return .pink
    case "食べ物": return .green
    case "人": return .purple
    case "生活": return .teal
    case "いつ": return .indigo
    default: return .gray
    }
}

